<script setup>
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue';
import ArtifactPreview from '../components/ArtifactPreview.vue';
import Modal from '../components/Modal.vue';
import { data, go, formatTime, removeArtifact } from '../lib/store.js';
import { typeInfo, downloadArtifact } from '../lib/artifacts.js';
const query = ref(''), filter = ref('all'), layout = ref('grid'), sort = ref('recent'), removing = ref(null);
const items = computed(() => data.artifacts.filter(a => (filter.value === 'all' || a.type === filter.value) && a.title.toLowerCase().includes(query.value.toLowerCase())).sort((a, b) => sort.value === 'recent' ? b.updatedAt.localeCompare(a.updatedAt) : a.title.localeCompare(b.title, 'zh-CN')));
</script>
<template>
  <div class="page library-page"><header class="page-heading"><div><span class="small-label">你的作品，集中在一处</span><h1>文件库</h1><p>从一个想法到一份作品，每一步都能找回。</p></div><button class="primary-button" @click="go('office')"><Icon name="Plus" :size="16" />新建作品</button></header>
    <div class="library-toolbar"><div class="filter-tabs"><button v-for="tab in [{ type: 'all', name: '全部文件' }, { type: 'diagram', name: '图表' }, { type: 'document', name: '文档' }, { type: 'table', name: '表格' }]" :key="tab.type" :class="{ active: filter === tab.type }" :aria-pressed="filter === tab.type" @click="filter = tab.type">{{ tab.name }}<span v-if="tab.type === 'all'">{{ data.artifacts.length }}</span></button></div><div class="library-tools"><label class="search-field"><Icon name="Search" :size="15" /><input v-model="query" placeholder="搜索文件…" aria-label="搜索文件" /></label><label class="sort-select"><select v-model="sort" aria-label="文件排序"><option value="recent">最近修改</option><option value="name">按名称</option></select></label><div class="view-toggle"><button class="icon-button" :class="{ active: layout === 'grid' }" :aria-pressed="layout === 'grid'" aria-label="卡片视图" @click="layout = 'grid'"><Icon name="LayoutGrid" :size="16" /></button><button class="icon-button" :class="{ active: layout === 'list' }" :aria-pressed="layout === 'list'" aria-label="列表视图" @click="layout = 'list'"><Icon name="AlignLeft" :size="16" /></button></div></div></div>
    <div v-if="items.length" class="library-items" :class="layout"><article v-for="item in items" :key="item.id" class="library-card"><button class="library-preview" :aria-label="'打开 ' + item.title" @click="go('workspace', item.sessionId)"><ArtifactPreview :type="item.type" :content="item.content" miniature /><span class="preview-tag">本地作品</span></button><div class="library-card-body"><button class="file-title-button" @click="go('workspace', item.sessionId)"><Icon :name="typeInfo[item.type].icon" :size="17" /><strong>{{ item.title }}</strong></button><div class="library-card-meta"><span>{{ typeInfo[item.type].label }} · v{{ item.revisions.length }}</span><time>{{ formatTime(item.updatedAt) }}</time></div></div><div class="library-card-actions"><button class="icon-button" :aria-label="'导出 ' + item.title" @click="downloadArtifact(item)"><Icon name="Download" :size="15" /></button><button class="icon-button" :aria-label="'删除 ' + item.title" @click="removing = item"><Icon name="Trash2" :size="15" /></button></div></article></div>
    <div v-else class="empty-state library-empty"><div class="empty-illustration"><span><Icon name="FileText" :size="28" /></span><span><Icon name="FolderOpen" :size="38" /></span><span><Icon name="Workflow" :size="26" /></span></div><h2>{{ data.artifacts.length ? '没有找到匹配的作品' : '为你的下一份作品，留好了位置' }}</h2><p>{{ data.artifacts.length ? '试试其他关键词，或查看全部文件。' : '创建图表、文档或表格，保存后便可在这里继续编辑。' }}</p><button v-if="data.artifacts.length" class="secondary-button" @click="query = ''; filter = 'all'">查看全部文件</button><button v-else class="primary-button" @click="go('office')"><Icon name="Plus" :size="16" />创建第一份作品</button></div>
    <footer class="page-footer"><span><Icon name="LockKeyhole" :size="13" />作品仅保存在当前浏览器，可在设置中导出备份</span><span>{{ items.length }} 个文件</span></footer>
  </div><Modal v-if="removing" title="删除作品" @close="removing = null"><p>删除「{{ removing.title }}」及其关联对话和版本记录？此操作无法撤销。</p><div class="modal-actions"><button class="secondary-button" @click="removing = null">保留作品</button><button class="danger-button" @click="removeArtifact(removing.id); removing = null">删除作品</button></div></Modal>
</template>
